<script setup>
import { onMounted, ref } from 'vue';import { useRoute } from 'vue-router';import { Gem, Wallet, Goal, Award, ArrowUpRight, ArrowDownRight, Minus, ShieldCheck } from '@lucide/vue'
import { api } from '../../services/api';import { money, number, positionName, date } from '../../utils'
import LoadingBlock from '../../components/LoadingBlock.vue';import EntityAvatar from '../../components/EntityAvatar.vue';import RankMovement from '../../components/RankMovement.vue';import HonourMedals from '../../components/HonourMedals.vue';import EmptyState from '../../components/EmptyState.vue'
const route=useRoute(),loading=ref(true),data=ref(null)
onMounted(async()=>{try{data.value=(await api.get(`/public/players/${route.params.id}`,null,{auth:false})).data}finally{loading.value=false}})
</script>
<template><div class="container page"><LoadingBlock v-if="loading"/><template v-else-if="data"><section class="player-hero glass"><EntityAvatar :src="data.dossier.photo_url" :name="data.dossier.full_name" :size="118" round/><div><span class="eyebrow">{{ positionName(data.dossier.position) }} · Số {{ data.dossier.shirt_number||'—' }}</span><h1>{{ data.dossier.full_name }}</h1><RouterLink v-if="data.dossier.club_id" :to="`/clubs/${data.dossier.club_id}`" class="club-link">{{ data.dossier.club_name }}</RouterLink><span v-else class="club-link">Cầu thủ tự do</span></div><div class="world-rank"><small>Hạng tổng thể</small><b>#{{ data.ranking?.overall_world_rank||'—' }}</b><RankMovement :change="data.ranking?.overall_rank_change" :previous="data.ranking?.overall_previous_rank"/></div></section><div class="grid-4 metrics"><article class="glass stat-card"><Gem :size="18" class="text-primary"/><div class="stat-value">{{ money(data.dossier.market_value,true) }}</div><div class="stat-label">Giá sàn tự động</div><div v-if="Number(data.dossier.latest_value_change)!==0" class="value-change" :class="Number(data.dossier.latest_value_change)>0?'text-green':'text-red'"><component :is="Number(data.dossier.latest_value_change)>0?ArrowUpRight:ArrowDownRight" :size="14"/>{{ Number(data.dossier.latest_value_change)>0?'+':'-' }}{{ money(Math.abs(Number(data.dossier.latest_value_change)),true) }}</div></article><article class="glass stat-card"><Wallet :size="18" class="text-green"/><div class="stat-value">{{ money(data.dossier.wallet_balance,true) }}</div><div class="stat-label">Tài sản cầu thủ</div></article><article class="glass stat-card"><Goal :size="18" class="text-yellow"/><div class="stat-value">{{ data.dossier.total_goals||0 }}</div><div class="stat-label">Tổng bàn thắng</div></article><article class="glass stat-card"><Award :size="18" class="text-primary"/><div class="stat-value">{{ data.honourSummary?.individual_award_count||0 }}</div><div class="stat-label">Danh hiệu cá nhân</div></article></div><section class="glass honour-strip"><div><span class="eyebrow">Bộ sưu tập huy chương</span><h3>Thành tích tập thể</h3></div><HonourMedals :gold="data.honourSummary?.gold_count" :silver="data.honourSummary?.silver_count" :bronze="data.honourSummary?.bronze_count"/><div class="individual-count"><b>{{ data.honourSummary?.individual_award_count||0 }}</b><span>Danh hiệu cá nhân</span></div></section><div class="profile-grid"><section class="glass card"><div class="section-title"><div><span class="eyebrow">Thành tích thi đấu</span><h2>Chỉ số sự nghiệp</h2></div></div><div class="career-stats"><div><b>{{ data.dossier.total_appearances||0 }}</b><span>Trận</span></div><div><b>{{ data.dossier.total_goals||0 }}</b><span>Bàn thắng</span></div><div><b>{{ data.dossier.total_assists||0 }}</b><span>Kiến tạo</span></div><div><b>{{ data.dossier.total_clean_sheets||0 }}</b><span>Giữ sạch lưới</span></div></div><div class="section-title inner"><div><span class="eyebrow">Biến động giá</span><h2>Lịch sử định giá</h2></div></div><EmptyState v-if="!data.values.length"/><div v-else class="value-timeline"><article v-for="item in data.values" :key="item.id"><span class="dot"></span><div><b>{{ money(item.new_value) }}</b><p>{{ item.reason }} · {{ date(item.changed_at,true) }}</p></div><component :is="Number(item.new_value)>Number(item.old_value)?ArrowUpRight:Number(item.new_value)<Number(item.old_value)?ArrowDownRight:Minus" :size="17" :class="Number(item.new_value)>=Number(item.old_value)?'text-green':'text-red'"/></article></div></section><section class="glass card"><div class="section-title"><div><span class="eyebrow">Danh hiệu vĩnh viễn</span><h2>Phòng truyền thống</h2></div></div><EmptyState v-if="!data.awards.length"/><div v-else class="award-list"><article v-for="award in data.awards" :key="award.player_award_id||award.id"><div class="medal">{{ award.required_medal_type==='GOLD'?'🥇':award.required_medal_type==='SILVER'?'🥈':award.required_medal_type==='BRONZE'?'🥉':'🏆' }}</div><div><b>{{ award.award_name }}</b><p>{{ award.competition_name }} · {{ award.season_name }}</p><small>{{ award.representing_name_at_award || award.club_name_at_award }} · {{ date(award.awarded_at) }}</small></div></article></div><div class="section-title inner"><div><span class="eyebrow">Lịch sử CLB</span><h2>Hành trình</h2></div></div><div class="history-list"><article v-for="item in data.history" :key="item.id"><ShieldCheck :size="17"/><div><b>{{ item.club_name }}</b><p>{{ date(item.joined_at) }} → {{ item.left_at?date(item.left_at):'Hiện tại' }}</p></div></article></div></section></div></template></div></template>
