-width:950px){.profile-grid{grid-template-columns:1fr}}@media(max-width:650px){.honour-strip{grid-template-columns:1fr}.individual-count{text-align:left}.player-hero{grid-template-columns:auto 1fr}.world-rank{grid-column:1/-1;text-align:left;display:flex;align-items:center;gap:12px}.world-rank b{font-size:32px}.career-stats{grid-template-columns:repeat(2,1fr)}}</style>
